exportedTypes.definition:
export interface ConfigOption {
  id: string;
  name: string;
  available: boolean;
  reason?: string;
}

export interface FieldCapability {
  state: FieldState;
  reason: string;
  required?: boolean;
  options?: ConfigOption[];
  min?: number;
  max?: number;
  step?: number;
  precision?: number;
  unit?: "CNY_MINOR" | "BEAN" | "RATIO";
  unitLabel?: string;
  allowedMin?: number[];
  allowedMax?: number[];
  maxSelected?: number;
  specs?: string[];
}

export interface ConfigurationContext {
  product: AdvertisingProduct;
  scenario: AdvertisingScenario;
  businessEntityId: string;
  accountId: string;
  shopId: string;
  objectiveId: string;
  optimizationId: string;
  strategyId: string;
  targetIds: string[];
  placementIds: string[];
  bidModeId: string;
  orderTypeId: string;
  fundTypeId: string;
  deliveryModeId: string;
  creativeMethodId: string;
}

export interface ConfigurationCapability {
  contractVersion: "advertising-v9.0";
  source: "API";
  tenantId: string;
  contextKey: string;
  version: string;
  checkedAt: string;
  expiresAt: string;
  fields: Partial<Record<FieldId, FieldCapability>>;
  authorization: "AUTHORIZED" | "UNAUTHORIZED" | "FORBIDDEN" | "NOT_INTEGRATED";
  writeChannel: "API" | "MANUAL" | "NONE";
  writePermission: string;
  audienceManagement: "MANUAL" | "PLATFORM_SMART";
  estimateSupported: boolean;
  uploadSupported: boolean;
  currency: "CNY" | "BEAN";
  reason: string;
  apiVersion: string;
  verification: {
    catalogIds: string[];
    pathVerified: boolean;
    applicationScopeGranted: boolean;
    accountAuthorized: boolean;
    backendIntegrated: boolean;
    requestSchemaVerified: boolean;
    executionVerified: boolean;
    proofId: string;
    checkedAt: string;
  };
}

export interface ConfigurationAccount {
  id: string;
  name: string;
  businessEntityId: string;
  shopIds: string[];
  authorization: ConfigurationCapability["authorization"];
  writable: boolean;
}

export interface ConfigurationCatalog {
  contractVersion: "advertising-v9.0";
  source: "API";
  tenantId: string;
  product: AdvertisingProduct;
  accounts: ConfigurationAccount[];
  entities: { id: string; name: string }[];
  shops: { id: string; name: string; businessEntityId: string }[];
  reason: string;
}

export interface SelectedResource {
  id: string;
  platformId: string;
  name: string;
  kind?: string;
  category?: string;
  parentId?: string;
  status?: string;
  eligible?: boolean;
  reason?: string;
  sourceMaterialId?: string;
  previewUrl?: string;
  specs?: string[];
}

export interface LookupPage {
  contractVersion: "advertising-v9.0";
  source: "API";
  tenantId: string;
  contextKey: string;
  kind: LookupKind;
  items: SelectedResource[];
  nextCursor: string | null;
  reason: string;
}

export interface AudienceConfiguration {
  mode: "CUSTOM" | "SMART" | "TEMPLATE";
  locationMode: "ANY" | "REGION" | "BUSINESS" | "CUSTOM";
  locations: SelectedResource[];
  locationTypeId: string;
  age: { min: string; max: string };
  gender: "ALL" | "MALE" | "FEMALE";
  interests: SelectedResource[];
  behaviors: SelectedResource[];
  intentions: SelectedResource[];
  keywords: SelectedResource[];
  creators: SelectedResource[];
  groups: SelectedResource[];
  include: SelectedResource[];
  exclude: SelectedResource[];
  behaviorSceneId: string;
  behaviorWindowId: string;
  behaviorIntensityId: string;
  expansion: boolean;
  hardConstraints: string[];
  platformTemplate: SelectedResource | null;
}

export interface AdvertisingDraft {
  schemaVersion: "advertising-draft-v1";
  id: string;
  updatedAt: string;
  product: AdvertisingProduct;
  scenario: AdvertisingScenario;
  businessEntityId: string;
  accountId: string;
  shopId: string;
  name: string;
  objectiveId: string;
  targets: SelectedResource[];
  placementIds: string[];
  optimizationId: string;
  strategyId: string;
  audience: AudienceConfiguration;
  budget: {
    typeId: string;
    amount: string;
    bidModeId: string;
    bidValue: string;
  };
  schedule: {
    start: string;
    end: string;
    allDay: boolean;
    slots: { days: number[]; start: string; end: string }[];
  };
  creative: {
    assets: SelectedResource[];
    title: string;
    copy: string;
    portrait: SelectedResource | null;
  };
  heating: {
    durationId: string;
    orderTypeId: string;
    fundTypeId: string;
    deliveryModeId: string;
    creativeMethodId: string;
  };
  productRangeId: string;
}

export interface LocalTargetingTemplate {
  id: string;
  name: string;
  product: AdvertisingProduct;
  scenario: AdvertisingScenario;
  accountId: string;
  audience: AudienceConfiguration;
  updatedAt: string;
}

export interface SubmissionTicket {
  idempotencyKey: string;
  draftId: string;
  product: AdvertisingProduct;
  accountId: string;
  contextKey: string;
  createdAt: string;
}

export interface AdvertisingStorage {
  drafts: AdvertisingDraft[];
  templates: LocalTargetingTemplate[];
  tickets: SubmissionTicket[];
}

export interface ConfigurationIssue {
  step: number;
  field: string;
  message: string;
}

export interface ReportModule {
  id: string;
  title: string;
  text: string;
  visible: boolean;
  showChart: boolean;
  showMetrics?: boolean;
  metricIds: string[];
  sectionId?: string;
}

export interface ReportDraft {
  schemaVersion: "business-report-v1";
  id: string;
  analysisId: string;
  title: string;
  period: ReviewPeriod;
  query: AnalysisQuery;
  shopName: string;
  platformName: string;
  source: "MOCK" | "API";
  updatedAt: string;
  version: number;
  metrics: AnalysisMetric[];
  points: AnalysisPoint[];
  sections: AnalysisSection[];
  insights: AnalysisInsight[];
  coverage: string;
  attribution: string;
  modules: ReportModule[];
}

export interface AnalysisQuery {
  shopId: string;
  platformId: ConnectorId | "all";
  startDate: string;
  endDate: string;
  dimensions: AnalysisDimension[];
  timezone: "Asia/Shanghai";
}

export interface AnalysisTask {
  id: string;
  query: AnalysisQuery;
  status: "queued" | "running" | "succeeded" | "failed";
  progress: number;
  resultId?: string;
  error?: string;
  createdAt: string;
}

export interface MetricDefinition {
  id: string; dimension: AnalysisDimension; name: string;
  unit: "minor" | "count" | "rate" | "ratio" | "hours";
  definition: string;
  numerator?: string; denominator?: string;
}

export interface AnalysisMetric extends MetricDefinition {
  value: number | null;
  previous: number | null;
  yearAgo: number | null;
  status: MetricStatus;
  reason?: string;
}

export interface AnalysisRow {
  id: string; name: string; date: string; values: Record<string, number | null>;
  relatedProduct?: string; relatedLive?: string;
}

export interface AnalysisSection {
  id: string;
  dimension: AnalysisDimension | "cross";
  title: string;
  topics: string[];
  metricIds: string[];
  rows: AnalysisRow[];
  conclusion: string;
  advice: string;
  limitation?: string;
}

export interface AnalysisInsight {
  id: string;
  kind: "conclusion" | "anomaly" | "opportunity" | "recommendation";
  title: string;
  evidence: string;
  direction: string;
  action: string;
  priority: "P1" | "P2" | "P3";
  verificationMetric: string;
  metricId: string;
  date?: string;
}

export interface AnalysisRules {
  declinePercent: number;
  spendRisePercent: number;
  roiFloor: number;
  minSpendMinor: number;
  minViews: number;
}

export interface AnalysisResult {
  schemaVersion: "business-analysis-v1";
  id: string;
  taskId: string;
  source: "MOCK" | "API";
  query: AnalysisQuery;
  shopName: string;
  platformName: string;
  createdAt: string;
  updatedAt: string | null;
  completeness: "complete" | "partial" | "empty";
  coverage: string;
  attribution: string;
  comparison: { previous: { startDate: string; endDate: string } | null; yearAgo: { startDate: string; endDate: string } | null };
  metrics: AnalysisMetric[];
  points: AnalysisPoint[];
  previousPoints: AnalysisPoint[];
  yearAgoPoints: AnalysisPoint[];
  sections: AnalysisSection[];
  insights: AnalysisInsight[];
  insightSource: "rules" | "ai";
  rules: AnalysisRules;
}

export type JobValue =
  | { kind: "MONEY"; currency: "CNY"; amount_minor: number }
  | { kind: "RATIO"; value: number }
  | { kind: "BOOLEAN"; value: boolean }
  | { kind: "HANDOFF"; value: "START" | "END" };

export interface RiskSummary {
  source: "MOCK" | "SERVER";
  result: "REVIEW_REQUIRED" | "BLOCKED" | "MANUAL_ONLY";
  level: "LOW" | "MEDIUM" | "HIGH";
  checks: { code: string; passed: boolean; message: string }[];
  policy_version: number;
  checked_at: string;
}

export interface JobApproval {
  state: "NOT_REQUESTED" | "PENDING" | "APPROVED" | "REJECTED";
  actor_id: string | null;
  decided_at: string | null;
  method: "MANUAL" | "SERVER_POLICY" | null;
  approved_version: number | null;
}

export interface JobReceipt {
  receipt_id: string;
  source: "MOCK" | "PLATFORM";
  platform_receipt_id: string | null;
  accepted: boolean | null;
  received_at: string | null;
  verification: "PENDING" | "MATCHED" | "MISMATCH" | "UNKNOWN";
  observed_value: JobValue | null;
  verified_at: string | null;
}

export interface JobError {
  code: string;
  message: string;
  retryable: boolean;
  at: string;
}

export interface CommandJob {
  schema_version: "1.0";
  job_id: string;
  source: JobSource;
  tenant_id: string;
  shop_id: string;
  account_id: string | null;
  live_session_id: string | null;
  target_type: "AD_PLAN" | "LIVE_SESSION";
  target_id: string;
  action_type: CommandAction;
  old_value: JobValue | null;
  new_value: JobValue;
  intent: string;
  status: JobStatus;
  created_at: string;
  updated_at: string;
  expires_at: string;
  risk_summary: RiskSummary;
  approval: JobApproval;
  execution_receipt: JobReceipt | null;
  error: JobError | null;
  version: number;
  idempotency_key: string;
  mode: "MOCK" | "API";
  history: { status: JobStatus; at: string; detail: string }[];
  mock_scenario?: MockScenario;
}

export interface ReportingScope {
  shop_id: string | "all";
  live_session_id: string | "all";
  connector_id: string | "all";
  date: string;
  timezone: "Asia/Shanghai";
}

export interface CreateJobRequest {
  source: JobSource;
  shop_id: string;
  target_type: CommandJob["target_type"];
  target_id: string;
  action_type: CommandAction;
  new_value: JobValue;
  intent: string;
  idempotency_key: string;
}

export interface JobVersionRequest {
  job_id: string;
  expected_version: number;
}

export type CommandInterpretation =
  | { kind: "QUERY"; text: string; live_session_id: string | null }
  | {
      kind: "ACTION";
      text: string;
      action_type: CommandAction;
      new_value: JobValue;
      target_type: CommandJob["target_type"];
      candidate_ids: string[];
    }
  | { kind: "UNRECOGNIZED"; text: string };

export interface Capability {
  status: Availability;
  reason: string;
  permission: string;
}

export interface PlatformCapabilities {
  platform: Platform;
  accountId: string;
  version: number;
  checkedAt: string;
  actions: Partial<Record<Action, Capability>>;
  execution: "COMMAND_JOB" | "DIRECT" | "MANUAL";
  automationMode: "OBSERVE" | "APPROVAL" | "CONTROLLED";
  refreshSeconds: number | null;
  maxAgeSeconds: number;
  supportedObjects: string[];
  supportedMetrics: string[];
  supportedFilters: string[];
  supportedColumns: string[];
  schema: {
    objectives: string[];
    targets: ("PRODUCT" | "VIDEO" | "LIVE")[];
    bidEditable: boolean;
    minAmount: number;
    maxAmount: number;
  };
}

export interface Shop {
  id: string;
  nativeId: string | null;
  tenantId: string;
  name: string;
}

export interface AdAccount {
  id: string;
  nativeId: string | null;
  shopId: string;
  platform: Platform;
  name: string;
  authorization: Availability;
  currency: "CNY" | "BEAN";
}

export interface DeliveryScope {
  platform: PlatformScope;
  shopId: string;
  accountId: string;
  start: string;
  end: string;
  liveSessionId?: string;
}

export interface PerformanceMetrics {
  spend: number | null;
  attributedGmvMinor: number | null;
  conversions: number | null;
  roi: number | null;
  attributionWindow: string | null;
  statisticDate: string | null;
  /** Only equal nonempty comparable keys may be aggregated. */
  comparableKey: string | null;
}

export interface LinkedObject {
  id: string;
  nativeId: string | null;
  type: "PRODUCT" | "VIDEO" | "LIVE" | "MATERIAL";
  name: string;
}

export interface Campaign extends DeliveryObject {
  platform: "adq";
  kind: "CAMPAIGN";
  level: "CAMPAIGN" | "ADGROUP" | "AD";
  budgetMinor: number;
  bidMinor: number;
  targetRoi: number | null;
  extensions: { objective?: string; startedAt?: string; endedAt?: string };
}

export interface PromotionOrder extends DeliveryObject {
  platform: "beans";
  kind: "PROMOTION_ORDER";
  contentType: "VIDEO" | "LIVE";
  contentId: string;
  heatingGoal: string;
  amountBeans: number;
  progress: number | null;
  startsAt: string | null;
  endsAt: string | null;
  extensions: { views: number | null; interactions: number | null };
}

export interface GoalBreakdown {
  id: string;
  type: "SHOP" | "PLATFORM" | "ACCOUNT" | "PLAN" | "LIVE";
  targetId: string;
  name: string;
  amountMinor: number;
}

export interface TrendPoint {
  date: string;
  actualGmvMinor: number | null;
  targetGmvMinor: number | null;
  spend: number | null;
  budget: number | null;
  roi: number | null;
  targetRoi: number | null;
  forecastGmvMinor?: number | null;
}

export interface BusinessGoal {
  id: string;
  nativeId: string | null;
  shopId: string;
  platform: PlatformScope;
  accountId: string | null;
  name: string;
  period: "DAY" | "WEEK" | "MONTH" | "LIVE" | "SHOP";
  start: string;
  end: string;
  status: "DRAFT" | "ACTIVE" | "CLOSED";
  version: number;
  gmvTargetMinor: number;
  budget: number;
  currency: "CNY" | "BEAN";
  roiFloor: number | null;
  actualBusinessGmvMinor: number | null;
  spent: number | null;
  actualRoi: number | null;
  breakdown: GoalBreakdown[];
  trends: TrendPoint[];
  history: {
    at: string;
    actor: string;
    before: string;
    after: string;
    version: number;
  }[];
}

export interface BudgetAllocation {
  id: string;
  shopId: string;
  platform: Platform;
  accountId: string;
  planId: string | null;
  version: number;
  currency: "CNY" | "BEAN";
  limit: number;
  allocated: number;
  spent: number | null;
  internalStatus: "DRAFT" | "PENDING_APPROVAL" | "APPROVED" | "REJECTED";
  platformStatus: "NOT_SUBMITTED" | "PENDING" | "ACCEPTED" | "FAILED";
  verificationStatus: "PENDING" | "MATCHED" | "UNKNOWN";
  approvalId: string | null;
  executionId: string | null;
}

export interface AccountFunds {
  accountId: string;
  balance: number | null;
  currency: "CNY" | "BEAN";
  syncedAt: string | null;
  warning: string | null;
}

export interface AIDecision {
  id: string;
  platform: Platform;
  shopId: string;
  accountId: string;
  planId: string;
  goalId: string | null;
  type: keyof typeof decisionTypes;
  title: string;
  explanation: string;
  recommendation: string;
  risk: "LOW" | "MEDIUM" | "HIGH";
  status:
    | "OPEN"
    | "DEFERRED"
    | "PENDING_APPROVAL"
    | "ACCEPTED"
    | "REJECTED"
    | "EXECUTED";
  discoveredAt: string;
  version: number;
  evidence: { label: string; value: string; sourceId: string }[];
  observation: {
    start: string;
    end: string;
    sampleSize: number | null;
    delayMinutes: number | null;
    confidence: string;
    limitations: string[];
  };
  proposedAction:
    | "CHANGE_DAILY_BUDGET"
    | "CHANGE_BID"
    | "PAUSE_AD_PLAN"
    | "RESUME_AD_PLAN"
    | null;
  proposedValue: number | boolean | null;
  impact: string | null;
  approvalId: string | null;
  executionId: string | null;
  outcome: string | null;
  history?: { at: string; actorId: string; status: string; comment: string }[];
}

export interface ApprovalRequest {
  id: string;
  accountId: string;
  before: unknown;
  after: unknown;
  reason: string;
  decisionId: string | null;
  budgetId: string | null;
  executionId: string | null;
  status: "PENDING" | "APPROVED" | "REJECTED";
  actorId: string | null;
  version: number;
}

export interface ExecutionTask {
  id: string;
  nativeId: string | null;
  platform: Platform;
  shopId: string;
  accountId: string;
  planId: string;
  goalId: string | null;
  decisionId: string | null;
  budgetId: string | null;
  approvalId: string | null;
  action: string;
  initiator: "MANUAL" | "AI" | "RULE";
  actorId: string | null;
  approverId: string | null;
  status: keyof typeof executionStates;
  before: unknown;
  after: unknown;
  version: number;
  createdAt: string;
  updatedAt: string;
  requestStatus: string;
  response: unknown;
  verification: string;
  failure: string | null;
  safeRetry: boolean;
  idempotencyKey: string | null;
  history: { at: string; status: string; detail: string }[];
  legacyJobId?: string;
}

export interface SyncStatus {
  state:
    | "READY"
    | "LOADING"
    | "EMPTY"
    | "UNAUTHORIZED"
    | "NOT_INTEGRATED"
    | "STALE"
    | "FAILED"
    | "FORBIDDEN";
  source: "API" | "MOCK";
  syncedAt: string | null;
  statisticStart: string;
  statisticEnd: string;
  message: string;
}

export interface RiskBoundaries {
  accountId: string;
  dailyLimit: number;
  singleChangeLimit: number;
  approvalThreshold: number;
  minObservationMinutes: number;
  maxChangesPerDay: number;
  currency: "CNY" | "BEAN";
  version: number;
}

export interface DeliveryData {
  contractVersion: "delivery-v8.0";
  scope: DeliveryScope;
  source: "API" | "MOCK";
  shops: Shop[];
  accounts: AdAccount[];
  capabilities: PlatformCapabilities[];
  plans: Plan[];
  goals: BusinessGoal[];
  decisions: AIDecision[];
  budgets: BudgetAllocation[];
  funds: AccountFunds[];
  executions: ExecutionTask[];
  approvals: ApprovalRequest[];
  boundaries: RiskBoundaries[];
  trends: { planId: string; points: TrendPoint[] }[];
  budgetTrends: { currency: "CNY" | "BEAN"; points: TrendPoint[] }[];
  sync: SyncStatus;
}

export interface PlanFilter {
  search: string;
  status: string;
  level: string;
  sort: "name" | "spend" | "updated";
  descending: boolean;
  page: number;
  pageSize: number;
  columns: string[];
}

export interface Tenant {
  id: string;
  name: string;
}

export interface Shop {
  id: string;
  tenantId: string;
  name: string;
  connectorId: ConnectorId;
}

export interface AdAccount {
  id: string;
  tenantId: string;
  shopId: string;
  connectorId: ConnectorId;
  name: string;
}

export interface LiveSession {
  id: string;
  tenantId: string;
  shopId: string;
  name: string;
  sourceUpdatedAt: string;
  fetchedAt: string;
  online: number | null;
  productClicks: number | null;
  status: "MOCK_LIVE" | "UNKNOWN" | "NOT_STARTED" | "LIVE" | "ENDED";
  /** Optional read-only fields; absent until supplied by the backend. */
  connectorId?: ConnectorId;
  coverUrl?: string | null;
  videoUrl?: string | null;
  startedAt?: string | null;
  endedAt?: string | null;
  totalViewers?: number | null;
  paidOrders?: number | null;
}

export interface AdPlan {
  id: string;
  nativePlanId: string;
  tenantId: string;
  shopId: string;
  adAccountId: string;
  liveSessionId?: string;
  name: string;
  aliases?: string[];
  budgetMinor: number;
  bidMinor: number;
  targetRoi: number;
  enabled: boolean;
  spendMinor: number | null;
  paidGmvMinor: number | null;
  sourceUpdatedAt: string;
  attributionWindow: string;
}

export interface Product {
  id: string;
  tenantId: string;
  shopId: string;
  skuId: string;
  name: string;
  priceMinor: number;
  stock: number | null;
  clicks: number | null;
  paidOrders: number | null;
  speechAdvice: string;
}

export interface Material {
  id: string;
  tenantId: string;
  productId: string;
  name: string;
  version: string;
  kind: "VIDEO" | "IMAGE" | "SCRIPT";
  status: "DRAFT" | "REVIEW" | "READY";
}

export interface RiskPolicy {
  id: string;
  tenantId: string;
  dailyBudgetMinor: number;
  targetRoi: number;
  maxChangePercent: number;
  cooldownMinutes: number;
  mode: "MANUAL" | "COPILOT" | "AUTOPILOT";
  version: number;
}

export interface ReplaySegment {
  id: string;
  liveSessionId: string;
  productId: string;
  startSeconds: number;
  endSeconds: number;
  transcript: string;
  advice: string;
  videoUrl: string | null;
}

export interface ReplayReport {
  id: string;
  liveSessionId: string;
  source: "MOCK" | "API";
  sections: { title: string; evidenceIds: string[]; text: string }[];
}

export interface Connector {
  id: ConnectorId;
  status: "UNKNOWN" | "READ_ONLY" | "SUPPORTED" | "UNSUPPORTED" | "DEGRADED";
  scopes: string[];
  checkedAt: string | null;
}

export interface FrontendSnapshot {
  schemaVersion: "command-job-v1.0";
  revision: number;
  source: "MOCK" | "API";
  tenants: Tenant[];
  shops: Shop[];
  adAccounts: AdAccount[];
  liveSessions: LiveSession[];
  plans: AdPlan[];
  products: Product[];
  materials: Material[];
  tasks: CommandJob[];
  scope: ReportingScope;
  riskPolicies: RiskPolicy[];
  replaySegments: ReplaySegment[];
  replayReports: ReplayReport[];
  connectors: Connector[];
}

export interface Identity {
  userId: string;
  displayName: string;
  email?: string;
  workspacePages?: string[];
